#!/usr/bin/env python3
"""Pure-standard-library implementation of the frozen selection protocol.

Discovery uses only the independent source CSV.  Review annotations cannot
change the queues; they can only accept, explicitly reject, or block a queued
candidate.  All weight comparisons use Decimal rather than binary floats.
"""

from __future__ import annotations

import csv
import hashlib
import io
import json
import sys
from decimal import Decimal, InvalidOperation
from pathlib import Path
from typing import Any, Iterable, Mapping
from urllib.parse import urlparse


FIELDS = ("id", "type", "name", "usersrated", "numweights", "averageweight")
QUOTAS = {"simple": 6, "medium": 4}
COVERAGE_FIELDS = ("setup", "actions", "terminal", "scoring", "special_rules", "components")
REJECT_STATUSES = frozenset({"reject_pages", "reject_access", "reject_incomplete", "reject_identity"})
ALIASES = {
    "id": {"id", "bggid", "objectid", "boardgameid"},
    "type": {"type", "itemtype", "objecttype"},
    "name": {"name", "primaryname", "gamename"},
    "usersrated": {"usersrated", "numratings", "numberofratings"},
    "numweights": {"numweights", "numweightratings", "numberofweightratings"},
    "averageweight": {"averageweight", "avgweight", "weight"},
}


class SelectionError(ValueError):
    """An input violates the frozen protocol; no implicit repair is made."""


def _csv_limit() -> None:
    limit = sys.maxsize
    while True:
        try:
            csv.field_size_limit(limit)
            return
        except OverflowError:
            limit //= 10


def _header_key(value: str) -> str:
    return "".join(c for c in value.lower() if c.isalnum())


def _decimal(value: Any) -> Decimal | None:
    if isinstance(value, bool) or value is None:
        return None
    try:
        result = Decimal(str(value).strip())
    except (InvalidOperation, ValueError):
        return None
    return result if result.is_finite() else None


def _integer(value: Any, *, positive: bool = False) -> int | None:
    number = _decimal(value)
    if number is None or number != number.to_integral_value():
        return None
    if number < (1 if positive else 0):
        return None
    return int(number)


def _canonical_row(row: Mapping[str, Any]) -> dict[str, str]:
    result = {"id": "", "type": str(row.get("type") or "").strip(),
              "name": str(row.get("name") or "").strip(), "usersrated": "",
              "numweights": "", "averageweight": ""}
    for key in ("id", "usersrated", "numweights"):
        number = _integer(row.get(key), positive=(key == "id"))
        result[key] = "" if number is None else str(number)
    # Preserve the source's entire finite decimal representation, including
    # trailing digits.  Missing/invalid values stay empty, never inferred.
    value = row.get("averageweight")
    if _decimal(value) is not None:
        result["averageweight"] = str(value).strip()
    return result


def normalize_source(raw_bytes: bytes) -> bytes:
    """Project every structurally valid source row to six canonical columns.

    No population, popularity, weight-range or game-name filtering happens
    here.  Invalid numeric fields become empty.  Malformed CSV or a missing /
    ambiguous required header raises SelectionError instead of dropping rows.
    """
    _csv_limit()
    try:
        text = raw_bytes.decode("utf-8-sig")
    except UnicodeDecodeError as exc:
        raise SelectionError("Source is not UTF-8 CSV") from exc
    reader = csv.reader(io.StringIO(text, newline=""), strict=True)
    try:
        header = next(reader)
    except (StopIteration, csv.Error) as exc:
        raise SelectionError("Source has no valid header") from exc
    indices: dict[str, int] = {}
    for field in FIELDS:
        matches = [i for i, key in enumerate(header) if _header_key(key) in ALIASES[field]]
        if len(matches) != 1:
            raise SelectionError(f"Required column {field!r} missing or ambiguous")
        indices[field] = matches[0]
    output = io.StringIO(newline="")
    writer = csv.DictWriter(output, fieldnames=FIELDS, lineterminator="\n")
    writer.writeheader()
    try:
        for line, values in enumerate(reader, start=2):
            if not values:
                continue
            if len(values) != len(header):
                raise SelectionError(f"Source CSV row {line}: inconsistent column count")
            writer.writerow(_canonical_row({field: values[index] for field, index in indices.items()}))
    except csv.Error as exc:
        raise SelectionError(f"Malformed source CSV: {exc}") from exc
    return output.getvalue().encode("utf-8")


def load_normalized(csv_bytes: bytes) -> list[dict[str, str]]:
    """Read normalized CSV without silently accepting different field names."""
    _csv_limit()
    try:
        reader = csv.DictReader(io.StringIO(csv_bytes.decode("utf-8-sig"), newline=""), strict=True)
        if tuple(reader.fieldnames or ()) != FIELDS:
            raise SelectionError(f"Normalized CSV must have columns {FIELDS}")
        rows = []
        for line, row in enumerate(reader, start=2):
            if None in row or any(value is None for value in row.values()):
                raise SelectionError(f"Normalized CSV row {line}: inconsistent column count")
            rows.append(_canonical_row(row))
        return rows
    except (UnicodeDecodeError, csv.Error) as exc:
        raise SelectionError(f"Invalid normalized CSV: {exc}") from exc


def build_queues(rows_or_bytes: bytes | Iterable[Mapping[str, Any]]) -> dict[str, list[dict[str, Any]]]:
    """Apply the population gates and return complete popularity-ordered queues.

    The review manifest and old selection are deliberately not arguments.
    Duplicate IDs with conflicting required data are errors, even if the
    conflicting row would later fail a population gate.
    """
    rows = load_normalized(rows_or_bytes) if isinstance(rows_or_bytes, bytes) else rows_or_bytes
    seen: dict[int, dict[str, str]] = {}
    queues: dict[str, list[dict[str, Any]]] = {key: [] for key in QUOTAS}
    for raw_row in rows:
        row = _canonical_row(raw_row)
        game_id = _integer(row["id"], positive=True)
        if game_id is None:
            continue
        if game_id in seen:
            previous = seen[game_id]
            equal = all(previous[key] == row[key] for key in FIELDS if key != "averageweight")
            equal = equal and _decimal(previous["averageweight"]) == _decimal(row["averageweight"])
            if not equal:
                raise SelectionError(f"Conflicting source records for BGG ID {game_id}")
            continue
        seen[game_id] = row
        weight = _decimal(row["averageweight"])
        usersrated = _integer(row["usersrated"])
        numweights = _integer(row["numweights"])
        if row["type"] != "boardgame" or weight is None or usersrated is None or numweights is None:
            continue
        if not Decimal("1") <= weight < Decimal("3") or usersrated < 1000 or numweights < 30:
            continue
        group = "simple" if weight < Decimal("2") else "medium"
        queues[group].append({"bgg_id": game_id, "name": row["name"],
                              "weight": row["averageweight"], "usersrated": usersrated,
                              "numweights": numweights})
    for games in queues.values():
        games.sort(key=lambda game: (-game["usersrated"], game["bgg_id"]))
    return queues


def _text(value: Any, label: str) -> str:
    if not isinstance(value, str) or not value.strip():
        raise SelectionError(f"{label} must be a nonempty string")
    return value.strip()


def _url(value: Any, label: str) -> str:
    value = _text(value, label)
    parsed = urlparse(value)
    if parsed.scheme not in ("http", "https") or not parsed.netloc:
        raise SelectionError(f"{label} must be an absolute HTTP(S) URL")
    return value


def _hash(value: Any, label: str) -> str:
    value = _text(value, label).lower()
    if len(value) != 64 or any(c not in "0123456789abcdef" for c in value):
        raise SelectionError(f"{label} must be a SHA-256 hex digest")
    return value


def validate_pass_review(review: Mapping[str, Any], *, local_root: Path | None = None) -> int:
    """Validate an explicit pass annotation, returning its total PDF pages.

    This checks the annotation contract, not the truth of its rule semantics.
    Optional local_path entries are hash-checked when local_root is supplied;
    they require a recorded SHA-256. Browser-only records require evidence.
    """
    if review.get("status") != "pass":
        raise SelectionError("Only an explicit pass review can be validated")
    if _integer(review.get("bgg_id"), positive=True) is None:
        raise SelectionError("Pass review needs a positive bgg_id")
    _text(review.get("source_identity"), "source_identity")
    _text(review.get("edition"), "edition")
    _url(review.get("source_page_url"), "source_page_url")
    coverage = review.get("coverage")
    if not isinstance(coverage, Mapping):
        raise SelectionError("Pass review needs six coverage annotations")
    for field in COVERAGE_FIELDS:
        item = coverage.get(field)
        if not isinstance(item, Mapping) or item.get("complete") is not True:
            raise SelectionError(f"Coverage {field!r} must be explicitly complete=True")
        _text(item.get("evidence"), f"coverage.{field}.evidence")
    pdf_docs = review.get("pdf_docs")
    if not isinstance(pdf_docs, list) or not pdf_docs:
        raise SelectionError("Pass review needs at least one full-rule PDF")
    page_total = 0
    urls: set[str] = set()
    for index, doc in enumerate(pdf_docs):
        if not isinstance(doc, Mapping):
            raise SelectionError(f"pdf_docs[{index}] must be an object")
        url = _url(doc.get("url"), f"pdf_docs[{index}].url")
        if url in urls:
            raise SelectionError("A PDF URL occurs more than once in one review")
        urls.add(url)
        pages = doc.get("pages")
        if isinstance(pages, bool) or not isinstance(pages, int) or pages < 1:
            raise SelectionError("Every original PDF page count must be a positive integer")
        page_total += pages
        if doc.get("verification") not in ("downloaded", "browser"):
            raise SelectionError("PDF verification must be downloaded or browser")
        _text(doc.get("evidence"), f"pdf_docs[{index}].evidence")
        if doc.get("verification") == "downloaded":
            _hash(doc.get("sha256"), f"pdf_docs[{index}].sha256")
        elif doc.get("sha256") is not None:
            _hash(doc["sha256"], f"pdf_docs[{index}].sha256")
        if doc.get("local_path") is not None:
            relative = Path(_text(doc["local_path"], f"pdf_docs[{index}].local_path"))
            digest = _hash(doc.get("sha256"), f"pdf_docs[{index}].sha256")
            if relative.is_absolute() or ".." in relative.parts:
                raise SelectionError("local_path must stay within the supplied local_root")
            if local_root is not None:
                path = (local_root / relative).resolve()
                if not path.is_relative_to(local_root.resolve()) or not path.is_file():
                    raise SelectionError(f"Missing or escaping local PDF: {relative}")
                if hashlib.sha256(path.read_bytes()).hexdigest() != digest:
                    raise SelectionError(f"Changed PDF invalidates review: {relative}")
    if not 1 <= page_total <= 9:
        raise SelectionError("Pass review original PDF burden must total 1–9 physical pages")
    html_docs = review.get("required_html")
    if not isinstance(html_docs, list):
        raise SelectionError("required_html must be an explicit list, including when empty")
    for index, doc in enumerate(html_docs):
        if not isinstance(doc, Mapping):
            raise SelectionError(f"required_html[{index}] must be an object")
        _url(doc.get("url"), f"required_html[{index}].url")
        _text(doc.get("evidence"), f"required_html[{index}].evidence")
        _text(doc.get("archive_evidence"), f"required_html[{index}].archive_evidence")
        if doc.get("sha256") is not None:
            _hash(doc["sha256"], f"required_html[{index}].sha256")
    return page_total


def select_reviewed(queues: Mapping[str, list[Mapping[str, Any]]],
                    reviews: Mapping[str | int, Mapping[str, Any]], *,
                    local_root: Path | None = None) -> dict[str, Any]:
    """Walk each queue without bypassing an unreviewed/pending predecessor.

    Returns explicit incomplete state and partial selections when blocked or
    exhausted. Malformed decisions raise SelectionError; they never become
    rejections. Every consumed pass is validated independently of its label.
    """
    if set(queues) != set(QUOTAS):
        raise SelectionError("Queues must contain exactly simple and medium strata")
    review_map: dict[int, Mapping[str, Any]] = {}
    for key, review in reviews.items():
        game_id = _integer(key, positive=True)
        if game_id is None or not isinstance(review, Mapping):
            raise SelectionError("Review map keys must be positive BGG IDs")
        if _integer(review.get("bgg_id"), positive=True) != game_id:
            raise SelectionError(f"Review identity differs from its key {key!r}")
        if game_id in review_map:
            raise SelectionError(f"Duplicate review key for BGG ID {game_id}")
        review_map[game_id] = review
    selected: list[dict[str, Any]] = []
    trace: list[dict[str, Any]] = []
    blocked: dict[str, dict[str, Any]] = {}
    shortfalls: dict[str, int] = {}
    for group, quota in QUOTAS.items():
        accepted = 0
        games = queues[group]
        expected = sorted(games, key=lambda game: (-game["usersrated"], game["bgg_id"]))
        if list(games) != expected:
            raise SelectionError(f"{group} queue is not in the frozen order")
        for position, game in enumerate(games, start=1):
            if accepted == quota:
                break
            game_id = game["bgg_id"]
            review = review_map.get(game_id)
            event = {"group": group, "queue_position": position, "bgg_id": game_id}
            if review is None or review.get("status") == "pending":
                event["status"] = "missing" if review is None else "pending"
                trace.append(event)
                blocked[group] = dict(event)
                break
            status = review.get("status")
            if status == "pass":
                pages = validate_pass_review(review, local_root=local_root)
                accepted += 1
                chosen = dict(game)
                chosen.update(group=group, queue_position=position, pdf_pages=pages)
                selected.append(chosen)
                event.update(status="pass", accepted_position=accepted)
            elif status in REJECT_STATUSES:
                event.update(status=status, reason=_text(review.get("reason"), "reject reason"))
            else:
                raise SelectionError(f"Unknown review status for BGG ID {game_id}: {status!r}")
            trace.append(event)
        shortfalls[group] = quota - accepted
    selected.sort(key=lambda game: (Decimal(game["weight"]), game["bgg_id"]))
    return {"selected": selected, "trace": trace, "complete": not any(shortfalls.values()),
            "shortfalls": shortfalls, "blocked": blocked}


def canonical_json_bytes(value: Any) -> bytes:
    """Stable JSON for candidate, selection and audit fingerprints."""
    return (json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"),
                       allow_nan=False) + "\n").encode("utf-8")


def canonical_sha256(value: Any) -> str:
    """Hash bytes directly or a JSON-compatible value in canonical form."""
    payload = value if isinstance(value, bytes) else canonical_json_bytes(value)
    return hashlib.sha256(payload).hexdigest()


