def unpack(payload):
    return zlib.decompress(base64.b64decode(payload))


def esc(value):
    return html.escape(str(value), quote=True)


def anchor(label, url, **attrs):
    extra = ' '.join(f'{esc(k)}="{esc(v)}"' for k, v in attrs.items())
    return f'<a href="{esc(url)}" target="_blank" rel="noopener noreferrer" {extra}>{esc(label)}</a>'


def json_download(label, value, filename):
    payload = base64.b64encode(canonical_json_bytes(value)).decode()
    return f'<a download="{esc(filename)}" href="data:application/json;base64,{payload}">{esc(label)}</a>'


def render_report(result, reviews, fingerprints, counts):
    total = len(result['selected'])
    completed = result['complete']
    lower = sum(g['group'] == 'simple' for g in result['selected'])
    rows = []
