def main(argv=None):
    parser = argparse.ArgumentParser(description='Discover candidates from an independent fixed BGG-derived snapshot; apply ordered, explicit rule audits.')
    parser.add_argument('--out-dir', type=Path, default=Path(__file__).resolve().parent)
    parser.add_argument('--reviews', type=Path, help='Use independently edited audit JSON instead of bundled annotations.')
    parser.add_argument('--discover-only', action='store_true', help='Generate both complete queues without reading any audit annotations.')
    parser.add_argument('--download-source', action='store_true', help='Re-download the pinned full Kaggle CSV, verify SHA-256 and independently regenerate its six-column projection.')
    parser.add_argument('--export-inputs', type=Path, metavar='DIR', help='Write the data projection, audit annotations, frozen protocol and provenance for inspection.')
    parser.add_argument('--explain', type=int, metavar='BGG_ID', help='Print source row, queue position and audited decision for one game.')
    args = parser.parse_args(argv)
    snapshot = unpack(PACKED_SOURCE)
    if canonical_sha256(snapshot) != NORMALIZED_SHA256:
        raise SelectionError('Bundled data projection was modified or corrupted')
    args.out_dir.mkdir(parents=True, exist_ok=True)
    if args.download_source:
        request = urllib.request.Request(SOURCE_METADATA['url'], headers={'User-Agent':'RulebookResearch/2.0'})
        with urllib.request.urlopen(request, timeout=120) as response:
            raw = response.read(150_000_001)
        if len(raw) > 150_000_000 or canonical_sha256(raw) != SOURCE_METADATA['raw_sha256']:
            raise SelectionError('Downloaded source differs from the pinned raw snapshot')
        regenerated = normalize_source(raw)
        if regenerated != snapshot:
            raise SelectionError('Raw-source normalization differs from the bundled projection')
        (args.out_dir/'source_bgg_original.csv').write_bytes(raw)
        print('PASS: independently downloaded raw CSV matches both original and normalized fingerprints.')
    queues = build_queues(snapshot)
    (args.out_dir/'candidate_queues.json').write_bytes(canonical_json_bytes(queues))
    print(f'Discovery: simple={len(queues["simple"])}; medium={len(queues["medium"])}; queue_sha256={canonical_sha256(queues)}')
    if args.discover_only:
        print('Discovery complete; no rule-audit annotations were read.')
        return 0
    review_bytes = args.reviews.read_bytes() if args.reviews else unpack(PACKED_REVIEWS)
    reviews = json.loads(review_bytes)
    if not isinstance(reviews, dict):
        raise SelectionError('Audit JSON must map BGG ID strings to review records')
    if args.export_inputs:
        args.export_inputs.mkdir(parents=True, exist_ok=True)
        (args.export_inputs/'bgg_snapshot.csv').write_bytes(snapshot)
        (args.export_inputs/'audit_records.json').write_bytes(canonical_json_bytes(reviews))
        (args.export_inputs/'protocol_frozen.md').write_bytes(unpack(PACKED_PROTOCOL))
        (args.export_inputs/'source_provenance.json').write_bytes(canonical_json_bytes(SOURCE_METADATA))
    if args.explain:
        location = next(({'group':group,'queue_position':i,'source_record':game} for group,games in queues.items() for i,game in enumerate(games,1) if game['bgg_id']==args.explain), None)
        print(json.dumps({'discovery':location,'review':reviews.get(str(args.explain)), 'source':SOURCE_METADATA},ensure_ascii=False,indent=2))
    result = select_reviewed(queues, reviews)
    fingerprints = {'data_projection_sha256':canonical_sha256(snapshot),'audit_records_sha256':canonical_sha256(reviews),'candidate_queues_sha256':canonical_sha256(queues),'protocol_sha256':canonical_sha256(unpack(PACKED_PROTOCOL))}
    payload = {'source':SOURCE_METADATA,'fingerprints':fingerprints,**result}
    (args.out_dir/'selection_result.json').write_bytes(canonical_json_bytes(payload))
    html_bytes = render_report(result, reviews, fingerprints, {'simple':len(queues['simple']),'medium':len(queues['medium']),'queues':queues}).encode('utf-8')
    (args.out_dir/'game_selection_report.html').write_bytes(html_bytes)
    for game in result['selected']:
        print(f'{game["bgg_id"]}\t{game["name"]}\t{game["weight"]}\t{game["pdf_pages"]} PDF pages\t{game["group"]} queue #{game["queue_position"]}')
    print('Report SHA256:',canonical_sha256(html_bytes))
    if not result['complete']:
        print('INCOMPLETE: quota shortfalls',json.dumps(result['shortfalls']),'; blocked predecessors',json.dumps(result['blocked']))
        return 2
    print('PASS: 10 selected; exactly 6 with Weight <2; all Weight <3; all explicit audits have 1–9 original PDF pages.')
    return 0


if __name__ == '__main__':
    try:
        raise SystemExit(main())
    except (SelectionError, OSError, ValueError) as error:
        print('ERROR:',error,file=sys.stderr)
        raise SystemExit(1)
